const fs = require("fs");
function readNum(name) {
  if (!fs.existsSync(name)) { console.error(`FAIL: required file ${name} is missing`); process.exit(1); }
  const raw = fs.readFileSync(name, "utf8").trim();
  if (raw === "") { console.error(`FAIL: ${name} is empty`); process.exit(1); }
  const n = Number(raw);
  if (!Number.isFinite(n)) { console.error(`FAIL: ${name} is not numeric: ${JSON.stringify(raw)}`); process.exit(1); }
  return n;
}
const seed = readNum("seed.txt");
const s1 = readNum("stage1.txt");
const s2 = readNum("stage2.txt");
const s3 = readNum("stage3.txt");
const checks = [
  ["stage1 = seed + 2", s1, seed + 2],
  ["stage2 = stage1^2", s2, s1 * s1],
  ["stage3 = stage2 - 4", s3, s2 - 4],
];
let ok = true;
console.log(`values: seed=${seed} stage1=${s1} stage2=${s2} stage3=${s3}`);
for (const [label, got, want] of checks) {
  const pass = got === want;
  if (!pass) ok = false;
  console.log(`${pass ? "PASS" : "FAIL"}: ${label} -> expected ${want}, found ${got}`);
}
if (!ok) { console.error("verification FAILED"); process.exit(1); }
console.log("all stage checks passed");
'

